// Narrow client for `codex app-server` over stdio (JSON-RPC, one JSON object per line).
// Message shapes are mapped from the schema generated by the installed binary
// (codex-cli 0.155.0-alpha.16.3): initialize / initialized, config/read, model/list,
// thread/start, turn/start, turn/interrupt; server requests for command, file-change,
// permission, user-input, elicitation, dynamic-tool, auth-refresh and attestation.
//
// The client owns one foreground process in its own process group. Leaf controls are
// applied as process-level config overrides and then CONFIRMED through config/read;
// if they cannot be confirmed the session refuses to start a thread. Every approval
// request is answered exactly once, by request id, from a role policy. Nothing here
// broadens the effective sandbox: escalation requests are declined.
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { childEnv, processGroupMembers, XaoError } from "../lib/util.mjs";

// Timers used only in races/grace periods must never keep the process alive.
const sleep = (ms) => new Promise((r) => setTimeout(r, ms).unref());

const CLIENT_INFO = { name: "cross-agent-orchestrator", title: "Cross-Agent Orchestrator", version: "0.1.0" };
const DELEGATION_ITEM_TYPES = new Set(["collabAgentToolCall", "subAgentActivity"]);

/** Read MCP server names and enabled plugin ids from config.toml without a TOML dependency. */
export function leafConfigTargets(configText) {
  const mcp = [...configText.matchAll(/^\[mcp_servers\.([A-Za-z0-9_-]+)\]\s*$/gm)].map((m) => m[1]);
  const plugins = [...configText.matchAll(/^\[plugins\."([^"]+)"\]\s*$/gm)].map((m) => m[1]);
  return { mcp: [...new Set(mcp)], plugins: [...new Set(plugins)] };
}

export function leafOverrides({ configText = "", network = false }) {
  const { mcp, plugins } = leafConfigTargets(configText);
  const kv = [
    ["features.multi_agent", "false"],
    ["features.multi_agent_v2.enabled", "false"],
    ["web_search", '"disabled"'],
    ["memories.generate_memories", "false"],
    ["memories.use_memories", "false"],
    ["notify", "[]"],
    ["sandbox_workspace_write.network_access", network ? "true" : "false"],
    ...mcp.map((n) => [`mcp_servers.${n}.enabled`, "false"]),
    // codex 0.155's -c parser splits on "." and does not honour quoted segments
    // (observed via config/read), so ids are passed bare. An id containing "." cannot
    // be addressed this way; it is left out and config/read confirmation then fails.
    ...plugins.filter((id) => !id.includes(".")).map((id) => [`plugins.${id}.enabled`, "false"]),
  ];
  return { args: kv.flatMap(([k, v]) => ["-c", `${k}=${v}`]), expect: { mcp, plugins, network } };
}

/** Check the effective config returned by config/read against what the leaf needs. */
export function confirmLeafControls(config, expect) {
  const problems = [];
  const f = config?.features ?? {};
  if (f.multi_agent !== false) problems.push(`features.multi_agent is ${JSON.stringify(f.multi_agent)}`);
  const v2 = f.multi_agent_v2;
  if (!(v2 === false || (v2 && typeof v2 === "object" && v2.enabled === false))) problems.push(`features.multi_agent_v2 is ${JSON.stringify(v2)}`);
  // Every MCP server / plugin in the EFFECTIVE config must be off, including any the
  // config.toml scan did not find (project layers, managed config).
  for (const [n, sv] of Object.entries(config?.mcp_servers ?? {})) {
    if (sv && sv.enabled !== false) problems.push(`mcp_servers.${n} still enabled${expect.mcp.includes(n) ? "" : " (not in config.toml; add an override)"}`);
  }
  for (const [id, pv] of Object.entries(config?.plugins ?? {})) {
    if (pv && pv.enabled !== false) problems.push(`plugin ${id} still enabled${expect.plugins.includes(id) ? "" : " (not in config.toml; add an override)"}`);
  }
  if (config?.web_search !== undefined && config.web_search !== "disabled" && config.web_search !== null) {
    problems.push(`web_search is ${JSON.stringify(config.web_search)}`);
  }
  return { confirmed: problems.length === 0, problems };
}

/**
 * Role policy. Returns {decision, reason} for one approval request.
 * reviewer/lead: never allow commands needing approval or any file change.
 * writer: never allow sandbox escalation; allow file changes only inside owned paths.
 */
export function roleApprovalPolicy({ role, cwd, ownedPaths = [] }) {
  const inOwned = (abs) => {
    if (!abs) return false;
    const rel = path.relative(cwd, path.resolve(cwd, abs));
    if (rel.startsWith("..") || path.isAbsolute(rel)) return false;
    return ownedPaths.length === 0 || ownedPaths.some((o) => rel === o || rel.startsWith(`${o.replace(/\/$/, "")}/`));
  };
  return (kind, params) => {
    switch (kind) {
      case "command":
        return { decision: "decline", reason: `${role}: commands needing approval would exceed the sandbox envelope` };
      case "fileChange":
        if (role !== "writer") return { decision: "decline", reason: `${role} is read-only` };
        if (params.grantRoot && !inOwned(params.grantRoot)) return { decision: "decline", reason: "grantRoot outside owned paths" };
        return { decision: "accept", reason: "writer file change within the workspace sandbox" };
      case "permissions":
        return { decision: "decline", reason: "no additional permissions are granted to leaf sessions" };
      default:
        return { decision: "decline", reason: `unsupported request kind ${kind}` };
    }
  };
}

const processGroupAlive = processGroupMembers;

export class CodexAppServerSession {
  /**
   * @param {object} o
   * @param {string} o.bin codex executable
   * @param {string} o.cwd workspace (the live checkout)
   * @param {"lead"|"reviewer"|"writer"|"verifier"} o.role
   * @param {string} o.model requested model id (as listed by model/list)
   * @param {string} [o.effort]
   * @param {string[]} [o.ownedPaths]
   * @param {boolean} [o.network]
   * @param {string} [o.configText] contents of the effective config.toml, used to find MCP/plugins
   * @param {function} [o.onEvent] receives every protocol message (for evidence logs)
   * @param {function} [o.policy] override approval policy (tests)
   * @param {string[]} [o.extraArgs] extra args placed before `app-server` (tests)
   */
  constructor(o) {
    Object.assign(this, { effort: null, ownedPaths: [], network: false, configText: "", onEvent: () => {}, extraArgs: [] }, o);
    this.policy = o.policy ?? roleApprovalPolicy({ role: o.role, cwd: o.cwd, ownedPaths: this.ownedPaths });
    this.nextId = 1;
    this.pendingClient = new Map(); // our requests awaiting responses
    this.answered = new Set(); // server request ids we already answered
    this.approvals = [];
    this.violations = [];
    this.items = [];
    this.agentText = [];
    this.tokenUsage = null;
    this.reroutes = [];
    this.turn = null;
    this.turnWaiters = [];
    this.stderrTail = [];
    this.exited = null;
  }

  // ---- transport ------------------------------------------------------------------
  spawnProcess() {
    const { args: leafArgs, expect } = leafOverrides({ configText: this.configText, network: this.network });
    this.expect = expect;
    const args = [...this.extraArgs, ...leafArgs, "app-server", "--listen", "stdio://"];
    this.proc = spawn(this.bin, args, {
      cwd: this.cwd,
      stdio: ["pipe", "pipe", "pipe"],
      detached: process.platform !== "win32", // own process group for owned cleanup
      env: { ...childEnv(process.env, { leaf: this.leaf !== false }), ...(this.env ?? {}) },
    });
    this.pid = this.proc.pid;
    this.pgid = process.platform !== "win32" ? this.proc.pid : null;
    this.exitPromise = new Promise((resolve) => {
      this.proc.once("exit", (code, signal) => {
        this.exited = { code, signal, at: Date.now() };
        for (const [, w] of this.pendingClient) w.reject(new XaoError("app_server_exited", `app-server exited (${code ?? signal})`));
        this.pendingClient.clear();
        this.resolveTurn({ type: "process_exit", code, signal });
        resolve(this.exited);
      });
    });
    this.proc.once("error", (error) => {
      this.spawnError = error;
    });
    this.proc.stderr.on("data", (chunk) => {
      this.stderrTail.push(String(chunk));
      if (this.stderrTail.length > 40) this.stderrTail.shift();
    });
    const rl = readline.createInterface({ input: this.proc.stdout });
    rl.on("line", (line) => this.onLine(line));
  }

  send(obj) {
    if (!this.proc || this.exited || this.proc.stdin.destroyed) throw new XaoError("app_server_closed", "app-server stdin is closed");
    this.proc.stdin.write(`${JSON.stringify(obj)}\n`);
  }

  request(method, params, timeoutMs = 30_000) {
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pendingClient.delete(id);
        reject(new XaoError("rpc_timeout", `${method} did not answer within ${timeoutMs}ms`));
      }, timeoutMs);
      this.pendingClient.set(id, {
        method,
        resolve: (v) => {
          clearTimeout(timer);
          resolve(v);
        },
        reject: (e) => {
          clearTimeout(timer);
          reject(e);
        },
      });
      try {
        this.send({ id, method, params });
      } catch (error) {
        clearTimeout(timer);
        this.pendingClient.delete(id);
        reject(error);
      }
    });
  }

  notify(method, params) {
    this.send(params === undefined ? { method } : { method, params });
  }

  onLine(line) {
    let msg;
    try {
      msg = JSON.parse(line);
    } catch {
      this.violations.push("non-JSON line on the protocol stream");
      return;
    }
    this.onEvent(msg);
    if (msg.id !== undefined && msg.method === undefined) {
      const waiter = this.pendingClient.get(msg.id);
      if (!waiter) return; // late/duplicate response: ignored, never re-delivered
      this.pendingClient.delete(msg.id);
      if (msg.error) waiter.reject(new XaoError("rpc_error", `${waiter.method}: ${msg.error.message ?? JSON.stringify(msg.error)}`, msg.error));
      else waiter.resolve(msg.result);
      return;
    }
    if (msg.id !== undefined && msg.method) return this.onServerRequest(msg);
    if (msg.method) return this.onNotification(msg);
  }

  respond(id, result) {
    if (this.answered.has(JSON.stringify(id))) throw new XaoError("duplicate_response", `Server request ${id} was already answered`);
    this.answered.add(JSON.stringify(id));
    this.send({ id, result });
  }

  respondError(id, message) {
    if (this.answered.has(JSON.stringify(id))) return;
    this.answered.add(JSON.stringify(id));
    this.send({ id, error: { code: -32601, message } });
  }

  onServerRequest(msg) {
    const { id, method, params = {} } = msg;
    if (this.answered.has(JSON.stringify(id))) {
      // A reused request id can never be authorized by an earlier answer.
      this.violations.push(`duplicate server request id ${id} (${method}) ignored`);
      return;
    }
    const record = (kind, decision, reason) =>
      this.approvals.push({ request: String(id), kind, decision, reason: `${reason}${params.command ? ` [${String(params.command).slice(0, 200)}]` : ""}` });
    if (this.turn?.id && params.turnId && params.turnId !== this.turn.id) {
      record(method, "decline", "request for a turn this client did not start");
      return this.respond(id, method.includes("fileChange") || method.includes("commandExecution") ? { decision: "cancel" } : {});
    }
    switch (method) {
      case "item/commandExecution/requestApproval": {
        const d = this.policy("command", params);
        record("command", d.decision, d.reason);
        return this.respond(id, { decision: d.decision === "accept" ? "accept" : "decline" });
      }
      case "item/fileChange/requestApproval": {
        const d = this.policy("fileChange", params);
        record("fileChange", d.decision, d.reason);
        return this.respond(id, { decision: d.decision === "accept" ? "accept" : "decline" });
      }
      case "item/permissions/requestApproval": {
        const d = this.policy("permissions", params);
        record("permissions", "decline", d.reason);
        return this.respond(id, { permissions: {}, scope: "turn" });
      }
      case "execCommandApproval":
      case "applyPatchApproval": {
        record(method, "denied", "legacy approval surface: denied");
        return this.respond(id, { decision: "denied" });
      }
      case "item/tool/requestUserInput":
        record("userInput", "unanswered", "leaf sessions cannot ask the user; assignment needs input");
        this.needsInput = true;
        return this.respond(id, { answers: {} });
      case "mcpServer/elicitation/request":
        record("elicitation", "decline", "MCP elicitation declined for leaf sessions");
        return this.respond(id, { action: "decline" });
      case "item/tool/call":
        record("dynamicTool", "error", "no dynamic tools are registered by this client");
        return this.respond(id, { contentItems: [], success: false });
      default:
        // account/chatgptAuthTokens/refresh, attestation/generate and anything unknown:
        // this client never manages credentials or attestations.
        record(method, "error", "not supported by this client");
        return this.respondError(id, `${method} is not supported by cross-agent-orchestrator`);
    }
  }

  onNotification({ method, params = {} }) {
    switch (method) {
      case "item/started":
      case "item/completed": {
        const item = params.item ?? {};
        if (DELEGATION_ITEM_TYPES.has(item.type)) {
          this.violations.push(`delegation attempted (${item.type})`);
          if (this.turn && !this.interruptSent) this.interrupt().catch(() => {});
        }
        if (method === "item/completed") {
          this.items.push({ type: item.type, id: item.id, status: item.status, command: item.command, exitCode: item.exitCode, changes: item.changes?.map?.((c) => c.path) });
          if (item.type === "agentMessage" && typeof item.text === "string") this.agentText.push(item.text);
        }
        return;
      }
      case "thread/tokenUsage/updated":
        if (!this.turn || params.turnId === this.turn.id) this.tokenUsage = params.tokenUsage; // cumulative: keep last
        return;
      case "model/rerouted":
        this.reroutes.push({ from: params.fromModel, to: params.toModel, reason: params.reason });
        return;
      case "turn/started":
        if (this.turn && params.turn?.id && !this.turn.id) this.turn.id = params.turn.id;
        return;
      case "turn/completed":
        if (this.turn && params.turn?.id === this.turn.id) this.resolveTurn({ type: "turn_completed", turn: params.turn });
        return;
      case "error":
        if (!params.willRetry && this.turn && params.turnId === this.turn.id) this.lastError = params.error;
        return;
      default:
        return;
    }
  }

  resolveTurn(outcome) {
    const waiters = this.turnWaiters;
    this.turnWaiters = [];
    this.turnOutcome = this.turnOutcome ?? outcome;
    for (const w of waiters) w(this.turnOutcome);
  }

  waitTurn(ms) {
    if (this.turnOutcome) return Promise.resolve(this.turnOutcome);
    return new Promise((resolve) => {
      const timer = setTimeout(() => resolve({ type: "timeout" }), ms);
      this.turnWaiters.push((o) => {
        clearTimeout(timer);
        resolve(o);
      });
    });
  }

  // ---- lifecycle -------------------------------------------------------------------
  async initialize() {
    this.spawnProcess();
    await new Promise((r) => setImmediate(r));
    if (this.spawnError) throw new XaoError("spawn_failed", this.spawnError.message);
    this.init = await this.request("initialize", { clientInfo: CLIENT_INFO, capabilities: { experimentalApi: false } });
    this.notify("initialized");
    const cfg = await this.request("config/read", { cwd: this.cwd });
    this.controls = confirmLeafControls(cfg?.config, this.expect);
    return { init: this.init, controls: this.controls };
  }

  async listModels() {
    const out = [];
    let cursor = null;
    for (let i = 0; i < 20; i += 1) {
      const res = await this.request("model/list", { cursor, includeHidden: false, limit: 100 });
      for (const m of res?.data ?? []) out.push({ id: m.id, model: m.model, displayName: m.displayName, efforts: (m.supportedReasoningEfforts ?? []).map((e) => e.reasoningEffort ?? e) });
      cursor = res?.nextCursor ?? null;
      if (!cursor) break;
    }
    return out;
  }

  async startThread({ developerInstructions }) {
    if (!this.controls?.confirmed) {
      throw new XaoError("controls_unconfirmed", `Leaf controls not confirmed: ${(this.controls?.problems ?? ["config/read unavailable"]).join("; ")}`);
    }
    const readOnly = this.role !== "writer";
    const res = await this.request("thread/start", {
      cwd: this.cwd,
      model: this.model,
      sandbox: readOnly ? "read-only" : "workspace-write",
      approvalPolicy: "on-request",
      developerInstructions,
      ephemeral: false,
    });
    this.thread = res.thread;
    this.threadInfo = { model: res.model, modelProvider: res.modelProvider, sandbox: res.sandbox, approvalPolicy: res.approvalPolicy, cwd: res.cwd, reasoningEffort: res.reasoningEffort ?? null };
    const s = res.sandbox;
    const sandboxType = typeof s === "string" ? s : s?.type ?? s?.mode ?? JSON.stringify(s);
    const okSandbox = readOnly ? /read.?only/i.test(sandboxType) : /workspace.?write/i.test(sandboxType);
    if (!okSandbox) {
      throw new XaoError("sandbox_mismatch", `Requested ${readOnly ? "read-only" : "workspace-write"} sandbox but the server reports ${sandboxType}`);
    }
    return this.threadInfo;
  }

  async runTurn(prompt, { timeoutMs = 20 * 60_000 } = {}) {
    this.turnOutcome = null;
    this.turn = { id: null };
    const res = await this.request("turn/start", {
      threadId: this.thread.id,
      input: [{ type: "text", text: prompt }],
      ...(this.effort ? { effort: this.effort } : {}),
    });
    this.turn.id = res?.turn?.id ?? this.turn.id;
    if (!this.turn.id) throw new XaoError("no_turn_id", "turn/start returned no turn id");
    let outcome = await this.waitTurn(timeoutMs);
    if (outcome.type === "timeout") {
      this.timedOut = true;
      await this.interrupt().catch(() => {});
      outcome = await this.waitTurn(15_000);
      if (outcome.type === "timeout") outcome = { type: "interrupt_unacknowledged" };
    }
    return outcome;
  }

  async interrupt() {
    if (!this.turn?.id || this.interruptSent) return;
    this.interruptSent = true;
    await this.request("turn/interrupt", { threadId: this.thread.id, turnId: this.turn.id }, 10_000);
  }

  /** Close stdin, wait, then escalate signals to the owned process group only. */
  async close({ graceMs = 5000 } = {}) {
    const steps = [];
    if (!this.proc) return { verified: true, detail: "no process was started", steps };
    if (!this.exited) {
      try {
        this.proc.stdin.end();
        steps.push("stdin closed");
      } catch {}
      await Promise.race([this.exitPromise, sleep(graceMs)]);
    }
    const signalGroup = (sig) => {
      try {
        if (this.pgid) process.kill(-this.pgid, sig);
        else this.proc.kill(sig);
        steps.push(`${sig} sent to ${this.pgid ? `process group ${this.pgid}` : `pid ${this.pid}`}`);
      } catch (error) {
        if (error.code !== "ESRCH") steps.push(`${sig} failed: ${error.code}`);
      }
    };
    if (!this.exited) {
      signalGroup("SIGTERM");
      await Promise.race([this.exitPromise, sleep(3000)]);
    }
    if (!this.exited) {
      signalGroup("SIGKILL");
      await Promise.race([this.exitPromise, sleep(3000)]);
    }
    // Descendants that outlived the leader in its group.
    let remaining = this.pgid ? processGroupAlive(this.pgid) : null;
    if (remaining && remaining.length > 0) {
      signalGroup("SIGTERM");
      await sleep(1500);
      remaining = processGroupAlive(this.pgid);
      if (remaining && remaining.length > 0) {
        signalGroup("SIGKILL");
        await sleep(500);
        remaining = processGroupAlive(this.pgid);
      }
    }
    const verified = Boolean(this.exited) && Array.isArray(remaining) && remaining.length === 0;
    const detail = `leader ${this.exited ? `exited (code ${this.exited.code}, signal ${this.exited.signal})` : "DID NOT EXIT"}; process group ${
      remaining === null ? "not checkable on this platform" : remaining.length === 0 ? "empty" : `still has ${remaining.join(",")}`
    }`;
    return { verified, detail, steps };
  }

  summary() {
    const requested = this.model;
    const observed = this.reroutes.length ? this.reroutes.at(-1).to : this.threadInfo?.model ?? null;
    return {
      requested_model: requested,
      observed_model: observed,
      model_provider: this.threadInfo?.modelProvider ?? null,
      model_mismatch: Boolean(observed && requested && observed !== requested),
      reroutes: this.reroutes,
      sandbox: this.threadInfo?.sandbox ?? null,
      approval_policy: this.threadInfo?.approvalPolicy ?? null,
      thread_id: this.thread?.id ?? null,
      turn_id: this.turn?.id ?? null,
      turn_status: this.turnOutcome?.turn?.status ?? this.turnOutcome?.type ?? null,
      turn_error: this.turnOutcome?.turn?.error?.message ?? this.lastError?.message ?? null,
      timed_out: Boolean(this.timedOut),
      needs_input: Boolean(this.needsInput),
      approvals: this.approvals,
      violations: this.violations,
      tools_used: [...new Set(this.items.map((i) => i.type))],
      commands: this.items.filter((i) => i.type === "commandExecution").map((i) => ({ command: i.command, exitCode: i.exitCode })),
      file_changes: this.items.filter((i) => i.type === "fileChange").flatMap((i) => i.changes ?? []),
      final_text: this.agentText.join("\n\n"),
      token_usage: this.tokenUsage,
      stderr_tail: this.stderrTail.join("").slice(-2000),
    };
  }
}

/** Discovery only: initialize, config/read, model/list, then close. No thread, no prompt. */
export async function probeAppServer({ bin, cwd, configText, extraArgs = [] }) {
  const s = new CodexAppServerSession({ bin, cwd, role: "reviewer", model: null, configText, extraArgs });
  try {
    const { init, controls } = await s.initialize();
    const models = await s.listModels();
    const cleanup = await s.close();
    return {
      ok: true,
      platform: init?.platformOs ?? null,
      user_agent: init?.userAgent ?? null,
      models: models.map((m) => m.model ?? m.id),
      model_details: models,
      controls_confirmed: controls.confirmed,
      control_problems: controls.problems,
      cleanup,
    };
  } catch (error) {
    const cleanup = await s.close();
    return { ok: false, error: error.message, stderr_tail: s.stderrTail.join("").slice(-1500), cleanup };
  }
}

export function readConfigText(codexHomeDir) {
  const f = path.join(codexHomeDir, "config.toml");
  return fs.existsSync(f) ? fs.readFileSync(f, "utf8") : "";
}
